before.content:
assertArrayEquals(hostFrame.toByteArray(), client.frames.getFirst());
RelayEnvelope wrongTenant = clientFrame.toBuilder().setTenantId("tenant-2").build();
assertThrows(RelayRouter.RelayRoutingException.class, () -> router.clientFrame(wrongTenant));
RelayEnvelope tooLarge = clientFrame.toBuilder().setOpaquePayload(ByteString.copyFrom(new byte[220])).build();
assertEquals("relay.quota_exceeded", assertThrows(RelayRouter.RelayRoutingException.class,
        () -> router.clientFrame(tooLarge)).code());

after.content:
assertArrayEquals(hostFrame.toByteArray(), client.frames.getFirst());
RelayEnvelope wrongTenant = clientFrame.toBuilder().setTenantId("tenant-2").build();
assertThrows(RelayRouter.RelayRoutingException.class, () -> router.clientFrame(wrongTenant));
RelayEnvelope wrongRoute = clientFrame.toBuilder().setRouteId("route-2").build();
assertThrows(RelayRouter.RelayRoutingException.class, () -> router.clientFrame(wrongRoute));
RelayEnvelope wrongDevice = clientFrame.toBuilder().setDeviceId("device-2").build();
assertThrows(RelayRouter.RelayRoutingException.class, () -> router.clientFrame(wrongDevice));
RelayEnvelope tooLarge = clientFrame.toBuilder().setOpaquePayload(ByteString.copyFrom(new byte[220])).build();
assertEquals("relay.quota_exceeded", assertThrows(RelayRouter.RelayRoutingException.class,
        () -> router.clientFrame(tooLarge)).code());
